-- leaving the bank at 3,770 and one progress row pointing at nothing. Choices
-- gain an explicit letter, nx_3af5a620 gains the blank its choices fill, and
-- the dead stem_text column is left null.
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('nx_3af5a62034e78102ad5ad11aaef44253', '', 'Reading & Writing', 'Standard English Conventions', 'Medium', 'Boundaries', '<h3>Passage</h3><p>Jamaican British artist Willard Wigan is known for his remarkable ______ so small that they are best viewed through a microscope, Wigan&#x27;s sculptures are made from tiny natural materials, such as spiderweb strands.</p><h3>Question</h3><p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>', '[{"letter":"A","content":"<p>microsculptures creations</p>"},{"letter":"B","content":"<p>microsculptures, creations</p>"},{"letter":"C","content":"<p>microsculptures. Creations</p>"},{"letter":"D","content":"<p>microsculptures and creations</p>"}]', '["C"]', '<p>Choice C is the best answer. &quot;Willard Wigan is known for his remarkable microsculptures&quot; and &quot;Creations so small that they are best viewed through a microscope, Wigan''s sculptures are made from tiny natural materials&quot; are both complete sentences, so a period is needed between them.</p><p>Choice A is incorrect. It runs the two sentences together with no punctuation. Choice B is incorrect. A comma alone cannot join two sentences. Choice D is incorrect. &quot;And&quot; does not repair the boundary, and the second half still stands as its own sentence.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m1_q12', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<p>The Post Office is a 1912 play by Rabindranath Tagore. Amal imagines people passing his window are carefree even when working, as when he says to a flower seller''s daughter: ______ Which quotation from The Post Office most effectively illustrates the claim?</p>', '[{"content":"“I see, you don’t wish to stop; I don’t care to stay on here either.”","letter":"A"},{"content":"“Oh, flower gathering? That is why your feet seem so glad and your anklets jingle so merrily as you walk.”","letter":"B"},{"content":"“I’ll pay when I grow up—before I leave to look for work out on the other side of that stream there.”","letter":"C"},{"content":"“Wish I could be out too. Then I would pick some flowers for you from the very topmost branches right out of sight.”","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The claim is that Amal pictures the people passing his window as carefree even when they are working. In choice B the flower seller''s daughter is at work gathering flowers, and Amal reads her walk as glad and her anklets as merry.</p><p>Choice A is incorrect. It is about Amal''s own restlessness. Choice C is incorrect. It concerns paying and leaving for work rather than how Amal pictures a worker. Choice D is incorrect. It expresses Amal''s wish to be outside, not his view of the people he watches.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m1_q13', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<figure class="image"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 300" width="520" height="300" role="img" aria-label="Bar graph of spider population count by day for enclosures with and without lizards. Day 1: no lizards 85, with lizards 85. Day 10: 62 and 32. Day 20: 51 and 27. Day 30: 43 and 23."><text x="260" y="16" font-size="13" text-anchor="middle">Spider Population Count</text><line x1="60" y1="240" x2="490" y2="240" stroke="#000"/><line x1="60" y1="40" x2="60" y2="240" stroke="#000"/><line x1="55" y1="240" x2="60" y2="240" stroke="#000"/><text x="50" y="244" font-size="11" text-anchor="end">0</text><line x1="55" y1="220" x2="60" y2="220" stroke="#000"/><text x="50" y="224" font-size="11" text-anchor="end">10</text><line x1="55" y1="200" x2="60" y2="200" stroke="#000"/><text x="50" y="204" font-size="11" text-anchor="end">20</text><line x1="55" y1="180" x2="60" y2="180" stroke="#000"/><text x="50" y="184" font-size="11" text-anchor="end">30</text><line x1="55" y1="160" x2="60" y2="160" stroke="#000"/><text x="50" y="164" font-size="11" text-anchor="end">40</text><line x1="55" y1="140" x2="60" y2="140" stroke="#000"/><text x="50" y="144" font-size="11" text-anchor="end">50</text><line x1="55" y1="120" x2="60" y2="120" stroke="#000"/><text x="50" y="124" font-size="11" text-anchor="end">60</text><line x1="55" y1="100" x2="60" y2="100" stroke="#000"/><text x="50" y="104" font-size="11" text-anchor="end">70</text><line x1="55" y1="80" x2="60" y2="80" stroke="#000"/><text x="50" y="84" font-size="11" text-anchor="end">80</text><line x1="55" y1="60" x2="60" y2="60" stroke="#000"/><text x="50" y="64" font-size="11" text-anchor="end">90</text><rect x="85" y="70" width="32" height="170" fill="#fff" stroke="#000"/><rect x="119" y="70" width="32" height="170" fill="#777" stroke="#000"/><text x="118" y="256" font-size="11" text-anchor="middle">1</text><rect x="190" y="116" width="32" height="124" fill="#fff" stroke="#000"/><rect x="224" y="176" width="32" height="64" fill="#777" stroke="#000"/><text x="223" y="256" font-size="11" text-anchor="middle">10</text><rect x="295" y="138" width="32" height="102" fill="#fff" stroke="#000"/><rect x="329" y="186" width="32" height="54" fill="#777" stroke="#000"/><text x="328" y="256" font-size="11" text-anchor="middle">20</text><rect x="400" y="154" width="32" height="86" fill="#fff" stroke="#000"/><rect x="434" y="194" width="32" height="46" fill="#777" stroke="#000"/><text x="433" y="256" font-size="11" text-anchor="middle">30</text><text x="275" y="274" font-size="12" text-anchor="middle">Day of experiment</text><text x="16" y="140" font-size="12" text-anchor="middle" transform="rotate(-90 16 140)">Spider count</text><rect x="300" y="36" width="14" height="12" fill="#fff" stroke="#000"/><text x="320" y="46" font-size="11">no lizards</text><rect x="390" y="36" width="14" height="12" fill="#777" stroke="#000"/><text x="410" y="46" font-size="11">with lizards</text></svg></figure><p>To investigate the effect of lizard predation on spider populations, a student in a biology class placed spiders in two enclosures, one with lizards and one without, and tracked the number of spiders in the enclosures for 30 days. The student concluded that the reduction in the spider population count in the enclosure with lizards by day 30 was entirely attributable to the presence of the lizards.</p><p>Which choice best describes data from the graph that weaken the student&rsquo;s conclusion?</p>', '[{"content":"Spider count was the same in both enclosures on day 1.","letter":"A"},{"content":"Spider count also substantially declined by day 30 in the enclosure without lizards.","letter":"B"},{"content":"The largest decline in the lizard enclosure occurred from day 1 to day 10.","letter":"C"},{"content":"Spider count on day 30 was lower in the lizard enclosure than the no-lizard enclosure.","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The student concluded that the drop in the lizard enclosure was entirely due to the lizards. The graph shows the spider count also fell substantially in the enclosure without lizards, so something besides predation was reducing both populations, which weakens the claim that the lizards account for the whole decline.</p><p>Choices A, C, and D are incorrect. Each describes the graph accurately, but none is inconsistent with the student''s conclusion.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m1_q18', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Form, Structure, and Sense', '<p>Racetrack Playa has 162 rocks that migrate. Racetrack-like trails in the ______ mysterious migration.</p>', '[{"content":"playas sediment mark the rock''s","letter":"A"},{"content":"playa''s sediment mark the rocks","letter":"B"},{"content":"playa''s sediment mark the rocks''","letter":"C"},{"content":"playas'' sediment mark the rocks''","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. Racetrack Playa is one place, so the possessive is the singular &quot;playa''s&quot;. The trails belong to many rocks, so the second possessive is the plural &quot;rocks''&quot;.</p><p>Choice A is incorrect. It makes &quot;playas&quot; a plain plural and the rock singular. Choice B is incorrect. &quot;Rocks&quot; is not possessive. Choice D is incorrect. &quot;Playas''&quot; is plural possessive, but the passage names a single playa.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m1_q22', NULL, 'Reading & Writing', 'Expression of Ideas', 'Medium', 'Transitions', '<p>A poll after the 1960 debate suggested Kennedy lost badly on radio. ______ the debate was ultimately considered a win for Kennedy among TV viewers.</p>', '[{"content":"In other words,","letter":"A"},{"content":"Therefore,","letter":"B"},{"content":"Likewise,","letter":"C"},{"content":"Nevertheless,","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The two halves contrast: the radio poll suggested Kennedy lost badly, yet the debate was ultimately judged a win among television viewers. &quot;Nevertheless&quot; marks that contrast.</p><p>Choice A is incorrect. Nothing is being restated. Choice B is incorrect. The second claim does not follow from the first. Choice C is incorrect. The two findings are opposed, not alike.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q06', NULL, 'Reading & Writing', 'Craft and Structure', 'Hard', 'Text Structure and Purpose', '<p>Wharton, House of Mirth: Lily ''could be keenly sensitive to a scene which was the fitting background of her own sensations.'' [Underlined:] The landscape outspread below her seemed an enlargement of her present mood... What is the function of the underlined sentence?</p>', '[{"content":"It creates a detailed image of the physical setting.","letter":"A"},{"content":"It establishes an internal conflict.","letter":"B"},{"content":"It makes an assertion the next sentence expands on.","letter":"C"},{"content":"It illustrates an idea introduced in the previous sentence.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The preceding sentence states that Lily is keenly sensitive to a scene that suits her own feelings; the underlined sentence then gives an instance, with the landscape reading as an enlargement of her mood.</p><p>Choice A is incorrect. The setting is described for what it reveals about Lily, not for its own sake. Choice B is incorrect. No conflict is set up. Choice C is incorrect. The sentence follows from the claim before it rather than being expanded on by what comes after.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q07', NULL, 'Reading & Writing', 'Craft and Structure', 'Hard', 'Text Structure and Purpose', '<p>Studies found little electoral cost to austerity, yet some European governments recently suffered for it. Huebscher et al. attribute this to a timing practice not followed in these cases. What is the function of the underlined sentence?</p>', '[{"content":"Explains a lab-vs-real-world discrepancy attributed to studies not using real-world data.","letter":"A"},{"content":"Identifies a conflict between research findings and recent events, later explained as a complicating factor in the data.","letter":"B"},{"content":"Presents a long-standing divergence attributed to different researchers using different data.","letter":"C"},{"content":"Describes a recent exception attributed to researchers underestimating data inconsistencies.","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The underlined sentence sets the earlier studies'' finding &mdash; little electoral cost to austerity &mdash; against recent European governments that did suffer for it, and the text then resolves that tension with a timing practice those governments did not follow.</p><p>Choice A is incorrect. The text does not attribute the gap to a lack of real-world data. Choice C is incorrect. The divergence is recent, not long-standing, and is not blamed on differing data sets. Choice D is incorrect. No one is said to have underestimated inconsistencies.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q08', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Central Ideas and Details', '<p>Adam Smith''s ''invisible hand'' metaphor was *putatively* used to model self-interest producing aggregate benefit; it was actually used once, narrowly, then elevated to a paradigm by 20th-century economists. What is the main idea?</p>', '[{"content":"The metaphor was ignored until economists realized it anticipated their views.","letter":"A"},{"content":"Economists gave it undue significance, but it''s still a useful model.","letter":"B"},{"content":"It was interpreted as a self-interest model but intended as a mercantilism critique.","letter":"C"},{"content":"The metaphor''s reputation isn''t due to its importance in Smith''s work but to later economists promoting it for their own ends.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The text''s point is that the &quot;invisible hand&quot; appears once, narrowly, in Smith''s work, and that its standing came from twentieth-century economists who elevated it to a paradigm for their own ends.</p><p>Choice A is incorrect. The text does not say the metaphor anticipated those economists'' views. Choice B is incorrect. The text does not endorse it as a useful model. Choice C is incorrect. The text does not claim Smith intended it as a critique of mercantilism.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q12', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<figure class="image"><table><caption>Employment by Sector in France and the United States, 1800&ndash;2012 (% of total employment)</caption><tr><th>Year</th><th>Agriculture in France</th><th>Manufacturing in France</th><th>Services in France</th><th>Agriculture in US</th><th>Manufacturing in US</th><th>Services in US</th></tr><tr><td>1800</td><td>64</td><td>22</td><td>14</td><td>68</td><td>18</td><td>13</td></tr><tr><td>1900</td><td>43</td><td>29</td><td>28</td><td>41</td><td>28</td><td>31</td></tr><tr><td>1950</td><td>32</td><td>33</td><td>35</td><td>14</td><td>33</td><td>53</td></tr><tr><td>2012</td><td>3</td><td>21</td><td>76</td><td>2</td><td>18</td><td>80</td></tr></table><figcaption style="font-size:12px">Rows in table may not add up to 100 due to rounding.</figcaption></figure><p>Over the past two hundred years, the percentage of the population employed in the agricultural sector has declined in both France and the United States, while employment in the service sector (which includes jobs in retail, consulting, real estate, etc.) has risen. However, this transition happened at very different rates in the two countries. This can be seen most clearly by comparing the employment by sector in both countries in ______</p><p>Which choice most effectively uses data from the table to complete the statement?</p>', '[{"content":"1900 with 1950","letter":"A"},{"content":"1800 with 2012","letter":"B"},{"content":"1900 with 2012","letter":"C"},{"content":"1800 with 1900","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. The claim is that the shift out of agriculture and into services happened at very different rates in the two countries. Between 1900 and 1950 agriculture in the US fell from 41% to 14% and services rose from 31% to 53%, while in France agriculture fell only from 43% to 32% and services from 28% to 35% &mdash; the same transition at very different speeds.</p><p>Choices B and C are incorrect. Both end at 2012, when the two countries look much alike, which hides the difference in rate. Choice D is incorrect. Between 1800 and 1900 the two countries change at broadly similar rates.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q14', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Inferences', '<p>Sweet potato is native to South America but cultivated in Polynesia before any sea voyages existed between them; DNA shows divergence 100,000+ years ago, Polynesia peopled only in the last 3,000 years. What did the team conclude?</p>', '[{"content":"Cultivation in Polynesia predates South America.","letter":"A"},{"content":"Polynesians acquired it from South Americans within the last 3,000 years.","letter":"B"},{"content":"Human activity likely played no role in introducing it to Polynesia.","letter":"C"},{"content":"Polynesian varieties descend from a domesticated South American variety.","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The Polynesian and South American plants diverged more than 100,000 years ago, while people reached Polynesia only within the last 3,000 years, so the sweet potato was already established there long before anyone could have carried it.</p><p>Choices B and D are incorrect. Both require the human transfer the dates rule out. Choice A is incorrect. The text does not compare when cultivation began in the two places.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q17', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Form, Structure, and Sense', '<p>...this period is remembered for its grandeur and artistry, its vehicles ______ by collectors for their ornate detailing and brass fittings.</p>', '[{"content":"are highly prized","letter":"A"},{"content":"had been highly prized","letter":"B"},{"content":"highly prized","letter":"C"},{"content":"were highly prized","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The sentence already has a main verb, &quot;is remembered&quot;. What follows the comma describes the vehicles, so it needs a participial phrase rather than a second finite verb.</p><p>Choices A, B, and D are incorrect. Each supplies a conjugated verb, producing two independent clauses joined by only a comma.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q22', NULL, 'Reading & Writing', 'Expression of Ideas', 'Medium', 'Transitions', '<p>Researchers report mathematicians traditionally worked alone, but evidence points to a shift. ______ mathematicians are choosing to collaborate, shown by a rise in multi-author publications.</p>', '[{"content":"Similarly,","letter":"A"},{"content":"For this reason,","letter":"B"},{"content":"Furthermore,","letter":"C"},{"content":"Increasingly,","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The sentence reports a change over time away from working alone, and &quot;Increasingly&quot; names that change; the rise in multi-author publications is the evidence for it.</p><p>Choices A and C are incorrect. Both would add a parallel point rather than mark a trend. Choice B is incorrect. It would claim a cause the text has not given.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_rw_m2_q23', NULL, 'Reading & Writing', 'Expression of Ideas', 'Medium', 'Transitions', '<p>The prime meridian (1884) was set using astronomically derived coordinates. ______ as decades passed, new calculations revealed increasingly precise coordinates, yet it stayed unchanged until the 1980s.</p>', '[{"content":"Specifically,","letter":"A"},{"content":"To that end,","letter":"B"},{"content":"Again and again,","letter":"C"},{"content":"Granted,","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The point is that new calculations produced more precise coordinates over and over across the decades while the meridian itself stayed put. &quot;Again and again&quot; conveys that repetition.</p><p>Choice A is incorrect. What follows is not an example of the preceding sentence. Choice B is incorrect. No purpose is being served. Choice D is incorrect. Nothing is being conceded.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_math_m2_q08', NULL, 'Math', 'Problem-Solving and Data Analysis', 'Hard', 'One-variable data: Distributions and measures of center and spread', '<p>The dot plots represent the distributions of values in data sets A and B.</p><figure class="image"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 185" width="700" height="185" role="img" aria-label="Two dot plots over values 10 to 16. Data Set A: 10 has 1 dot, 11 has 4, 12 has 2, 13 has 3, 14 has 2, 15 has 4, 16 has 1. Data Set B: 10 has 2 dots, 11 has 4, 12 has 2, 13 has 1, 14 has 2, 15 has 4, 16 has 2."><text x="128" y="16" font-size="13" text-anchor="middle">Data Set A</text><line x1="20" y1="150" x2="236" y2="150" stroke="#000" stroke-width="1.5"/><line x1="28" y1="150" x2="28" y2="156" stroke="#000" stroke-width="1.5"/><text x="28" y="172" font-size="12" text-anchor="middle">10</text><circle cx="28" cy="140" r="7" fill="#000"/><line x1="61" y1="150" x2="61" y2="156" stroke="#000" stroke-width="1.5"/><text x="61" y="172" font-size="12" text-anchor="middle">11</text><circle cx="61" cy="140" r="7" fill="#000"/><circle cx="61" cy="118" r="7" fill="#000"/><circle cx="61" cy="96" r="7" fill="#000"/><circle cx="61" cy="74" r="7" fill="#000"/><line x1="94" y1="150" x2="94" y2="156" stroke="#000" stroke-width="1.5"/><text x="94" y="172" font-size="12" text-anchor="middle">12</text><circle cx="94" cy="140" r="7" fill="#000"/><circle cx="94" cy="118" r="7" fill="#000"/><line x1="127" y1="150" x2="127" y2="156" stroke="#000" stroke-width="1.5"/><text x="127" y="172" font-size="12" text-anchor="middle">13</text><circle cx="127" cy="140" r="7" fill="#000"/><circle cx="127" cy="118" r="7" fill="#000"/><circle cx="127" cy="96" r="7" fill="#000"/><line x1="160" y1="150" x2="160" y2="156" stroke="#000" stroke-width="1.5"/><text x="160" y="172" font-size="12" text-anchor="middle">14</text><circle cx="160" cy="140" r="7" fill="#000"/><circle cx="160" cy="118" r="7" fill="#000"/><line x1="193" y1="150" x2="193" y2="156" stroke="#000" stroke-width="1.5"/><text x="193" y="172" font-size="12" text-anchor="middle">15</text><circle cx="193" cy="140" r="7" fill="#000"/><circle cx="193" cy="118" r="7" fill="#000"/><circle cx="193" cy="96" r="7" fill="#000"/><circle cx="193" cy="74" r="7" fill="#000"/><line x1="226" y1="150" x2="226" y2="156" stroke="#000" stroke-width="1.5"/><text x="226" y="172" font-size="12" text-anchor="middle">16</text><circle cx="226" cy="140" r="7" fill="#000"/><text x="508" y="16" font-size="13" text-anchor="middle">Data Set B</text><line x1="400" y1="150" x2="616" y2="150" stroke="#000" stroke-width="1.5"/><line x1="408" y1="150" x2="408" y2="156" stroke="#000" stroke-width="1.5"/><text x="408" y="172" font-size="12" text-anchor="middle">10</text><circle cx="408" cy="140" r="7" fill="#000"/><circle cx="408" cy="118" r="7" fill="#000"/><line x1="441" y1="150" x2="441" y2="156" stroke="#000" stroke-width="1.5"/><text x="441" y="172" font-size="12" text-anchor="middle">11</text><circle cx="441" cy="140" r="7" fill="#000"/><circle cx="441" cy="118" r="7" fill="#000"/><circle cx="441" cy="96" r="7" fill="#000"/><circle cx="441" cy="74" r="7" fill="#000"/><line x1="474" y1="150" x2="474" y2="156" stroke="#000" stroke-width="1.5"/><text x="474" y="172" font-size="12" text-anchor="middle">12</text><circle cx="474" cy="140" r="7" fill="#000"/><circle cx="474" cy="118" r="7" fill="#000"/><line x1="507" y1="150" x2="507" y2="156" stroke="#000" stroke-width="1.5"/><text x="507" y="172" font-size="12" text-anchor="middle">13</text><circle cx="507" cy="140" r="7" fill="#000"/><line x1="540" y1="150" x2="540" y2="156" stroke="#000" stroke-width="1.5"/><text x="540" y="172" font-size="12" text-anchor="middle">14</text><circle cx="540" cy="140" r="7" fill="#000"/><circle cx="540" cy="118" r="7" fill="#000"/><line x1="573" y1="150" x2="573" y2="156" stroke="#000" stroke-width="1.5"/><text x="573" y="172" font-size="12" text-anchor="middle">15</text><circle cx="573" cy="140" r="7" fill="#000"/><circle cx="573" cy="118" r="7" fill="#000"/><circle cx="573" cy="96" r="7" fill="#000"/><circle cx="573" cy="74" r="7" fill="#000"/><line x1="606" y1="150" x2="606" y2="156" stroke="#000" stroke-width="1.5"/><text x="606" y="172" font-size="12" text-anchor="middle">16</text><circle cx="606" cy="140" r="7" fill="#000"/><circle cx="606" cy="118" r="7" fill="#000"/></svg></figure><p>Which of the following statements must be true?</p><p>I. The median of data set A is equal to the median of data set B.<br>II. The standard deviation of data set A is equal to the standard deviation of data set B.</p>', '[{"content":"I only","letter":"A"},{"content":"II only","letter":"B"},{"content":"I and II","letter":"C"},{"content":"Neither I nor II","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. Each data set has 17 values, so the median of each is the 9th value in order. In data set A the counts for 10 through 16 are 1, 4, 2, 3, 2, 4, 1, so the 9th value is 13; in data set B they are 2, 4, 2, 1, 2, 4, 2, and the 9th value is also 13. Statement I is true.</p><p>Statement II is false. Data set B has more of its values at the extremes, 10 and 16, and fewer near the center, so its values are more spread out about the mean and its standard deviation is larger. Choices B, C, and D are incorrect because only statement I must be true.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_math_m2_q16', NULL, 'Math', 'Geometry and Trigonometry', 'Hard', 'Circles', '<p>Which equation represents a circle that intersects the y-axis at exactly one point?</p>', '[{"content":"(x-8)²+(y-8)²=16","letter":"A"},{"content":"(x-8)²+(y-4)²=16","letter":"B"},{"content":"(x-4)²+(y-9)²=16","letter":"C"},{"content":"x²+(y-9)²=16","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. A circle meets the y-axis at exactly one point when it is tangent to that axis, which happens when the distance from its center to the y-axis equals its radius. Every choice has r&#178; = 16, so r = 4, and choice C''s center is 4 units from the y-axis.</p><p>Choices A and B are incorrect. Both centers are 8 units from the y-axis, more than the radius, so those circles never reach it. Choice D is incorrect. Its center is on the y-axis, so that circle crosses the axis at two points.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt10_math_m2_q22', NULL, 'Math', 'Algebra', 'Hard', 'Linear functions', '<p>$220 for the first 2 hours, plus an hourly fee after. Total cost for 5 hours = $400.</p><p><strong>Which f(x) gives total cost for x &ge; 2 hours?</strong></p>', '[{"content":"f(x)=60x+100","letter":"A"},{"content":"f(x)=60x+220","letter":"B"},{"content":"f(x)=80x","letter":"C"},{"content":"f(x)=80x+220","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. The first 2 hours cost $220, and 5 hours cost $400, so the 3 additional hours cost $180 &mdash; an hourly fee of $60. For x &ge; 2 the total is 220 + 60(x &minus; 2) = 60x + 100, and f(5) = 400 as required.</p><p>Choice B is incorrect. It adds the hourly fee to the full $220 without accounting for the 2 hours that fee already covers. Choices C and D are incorrect. Both use an hourly fee of $80, which does not give a total of $400 at 5 hours.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m1_q5', NULL, 'Reading & Writing', 'Craft and Structure', NULL, 'Words in Context', '<p>Some economic historians ______ that late nineteenth- and early twentieth-century households in the United States experienced an economy of scale when it came to food purchases&mdash;they assumed that large households spent less on food per person than did small households. Economist Trevon Logan showed, however, that a close look at the available data disproves this supposition.</p><p><strong>Which choice completes the text with the most logical and precise word or phrase?</strong></p>', '[{"content":"surmised","letter":"A"},{"content":"contrived","letter":"B"},{"content":"questioned","letter":"C"},{"content":"regretted","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. The blank describes what the historians did with an idea they had not verified &mdash; they assumed it, as the next clause says, and Logan later disproved it. &quot;Surmised&quot; means supposed without conclusive evidence.</p><p>Choice B is incorrect. &quot;Contrived&quot; suggests deliberate fabrication. Choice C is incorrect. Questioning the idea is the opposite of assuming it. Choice D is incorrect. &quot;Regretted&quot; does not describe holding a belief.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m1_q9', NULL, 'Reading & Writing', 'Information and Ideas', NULL, 'Central Ideas and Details', '<p><em>Adapted from Jack London''s 1903 novel</em> The Call of the Wild. <em>Buck is a sled dog living with John Thornton in Yukon, Canada.</em></p><p>Thornton alone held [Buck]. The rest of mankind was as nothing. Chance travellers might praise or pet him; but he was cold under it all, and from a too demonstrative man he would get up and walk away. When Thornton''s partners, Hans and Pete, arrived on the long-expected raft, Buck refused to notice them till he learned they were close to Thornton; after that he tolerated them in a passive sort of way, accepting favors from them as though he favored them by accepting.</p><p><strong>Which choice best states the main idea of the text?</strong></p>', '[{"content":"Buck has become less social since he began living with Thornton.","letter":"A"},{"content":"Buck mistrusts humans and does his best to avoid them.","letter":"B"},{"content":"Buck has been especially well liked by most of Thornton''s friends.","letter":"C"},{"content":"Buck holds Thornton in higher regard than any other person.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. Every detail sets Thornton apart: the rest of mankind is &quot;as nothing&quot;, strangers leave Buck cold, and even Thornton''s partners are tolerated only passively and only once Buck learns they are close to Thornton.</p><p>Choice A is incorrect. The text describes no change over time. Choice B is incorrect. Buck is indifferent to other people rather than mistrustful of them. Choice C is incorrect. The passage is about Buck''s regard for others, not theirs for him.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m1_q20', NULL, 'Reading & Writing', 'Standard English Conventions', NULL, 'Form, Structure, and Sense', '<p>A model created by biologist Luis Valente predicts that the rate of speciation&mdash;the rate at which new species form&mdash;on an isolated island located approximately 5,000 kilometers from the nearest mainland ______ triple the rate of speciation on an island only 500 kilometers from the mainland.</p><p><strong>Which choice completes the text so that it conforms to the conventions of Standard English?</strong></p>', '[{"content":"being","letter":"A"},{"content":"to be","letter":"B"},{"content":"to have been","letter":"C"},{"content":"will be","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The subject is &quot;the rate of speciation&quot;, and the sentence needs a finite verb for it. &quot;Will be&quot; supplies one.</p><p>Choices A, B, and C are incorrect. &quot;Being&quot;, &quot;to be&quot;, and &quot;to have been&quot; are all non-finite, leaving the sentence with no main verb.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q2', NULL, 'Reading & Writing', 'Craft and Structure', NULL, 'Words in Context', '<p>New and interesting research conducted by Suleiman A. Al-Sweedan and Moath Alhaj is inspired by their observation that though there have been many studies of the effect of high altitude on blood chemistry, there is a ______ studies of the effect on blood chemistry of living in locations below sea level, such as the California towns of Salton City and Seeley.</p><p><strong>Which choice completes the text with the most logical and precise word or phrase?</strong></p>', '[{"content":"quarrel about","letter":"A"},{"content":"paucity of","letter":"B"},{"content":"profusion of","letter":"C"},{"content":"verisimilitude in","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The sentence contrasts the many studies of high altitude with the scarcity of studies of life below sea level. &quot;A paucity of&quot; means a shortage.</p><p>Choice C is incorrect. &quot;A profusion of&quot; means the opposite. Choices A and D are incorrect. Neither &quot;a quarrel about&quot; nor &quot;verisimilitude in&quot; fits a comparison of how much research exists.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q3', NULL, 'Reading & Writing', 'Craft and Structure', NULL, 'Words in Context', '<p>Whether the reign of a French monarch such as Hugh Capet or Henry I was historically consequential or relatively uneventful, its trajectory was shaped by questions of legitimacy and therefore cannot be understood without a corollary understanding of the factors that allowed the monarch to ______ his right to hold the throne.</p><p><strong>Which choice completes the text with the most logical and precise word or phrase?</strong></p>', '[{"content":"disengage","letter":"A"},{"content":"annotate","letter":"B"},{"content":"buttress","letter":"C"},{"content":"reciprocate","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The sentence concerns what allowed a monarch to strengthen his claim to the throne, and &quot;buttress&quot; means to support or reinforce.</p><p>Choice A is incorrect. &quot;Disengage&quot; means the opposite. Choices B and D are incorrect. Neither annotating nor reciprocating applies to a claim of legitimacy.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q5', NULL, 'Reading & Writing', 'Craft and Structure', NULL, 'Text Structure and Purpose', '<p><em>Adapted from</em> Indian Boyhood, <em>a 1902 memoir by Ohiyesa (Charles A. Eastman), a Santee Dakota writer. Ohiyesa recalls how the women in his tribe harvested maple syrup.</em></p><p>Now the women began to test the trees&mdash;moving leisurely among them, axe in hand, and striking a single quick blow, to see if the sap would appear. <u>The trees, like people, have their individual characters; some were ready to yield up their life-blood, while others were more reluctant.</u> Now one of the birchen basins was set under each tree, and a hardwood chip driven deep into the cut which the axe had made. From the corners of this chip&mdash;at first drop by drop, then more freely&mdash;the sap trickled into the little dishes.</p><p><strong>Which choice best describes the function of the underlined sentence in the text as a whole?</strong></p>', '[{"content":"It portrays the range of personality traits displayed by the women as they work.","letter":"A"},{"content":"It foregrounds the beneficial relationship between humans and maple trees.","letter":"B"},{"content":"It demonstrates how human behavior can be influenced by the natural environment.","letter":"C"},{"content":"It elaborates on an aspect of the maple trees that the women evaluate.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The sentence before describes the women testing each tree with a single blow of the axe; the underlined sentence explains what that test reveals, namely that some trees give up their sap readily and others do not.</p><p>Choice A is incorrect. It is the trees, not the women, that are being characterized. Choices B and C are incorrect. The passage draws no lesson about mutual benefit or about the environment shaping human behavior.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q14', NULL, 'Reading & Writing', 'Information and Ideas', NULL, 'Command of Evidence', '<p>While attending school in New York City in the 1980s, Okwui Enwezor encountered few works by African artists in exhibitions, despite New York''s reputation as one of the best places to view contemporary art from around the world. According to an arts journalist, later in his career as a renowned curator and art historian, Enwezor sought to remedy this deficiency, <strong>not by focusing solely on modern African artists, but by showing how their work fits into the larger context of global modern art and art history</strong>.</p><p><strong>Which finding, if true, would most directly support the journalist''s claim?</strong></p>', '[{"content":"As curator of the Haus der Kunst in Munich, Enwezor organized a retrospective of Ghanaian sculptor El Anatsui''s work, one of the largest exhibitions devoted to a Black artist in Europe''s history.","letter":"A"},{"content":"In Postwar: Art Between the Pacific and the Atlantic, 1945-1965, Enwezor and cocurator Katy Siegel brought works by African artists such as Malangatana Ngwenya together with pieces by major figures from other countries, like US artist Andy Warhol and Mexico''s David Siqueiros.","letter":"B"},{"content":"Enwezor''s work as curator of The Short Century: Independence and Liberation Movements in Africa, 1945-1994 showed how African independence movements profoundly influenced work by African artists of the period, such as Kamala Ibrahim Ishaq and Thomas Mukarobgwa.","letter":"C"},{"content":"Enwezor organized In/sight: African Photographers, 1940 to the Present not to emphasize a particular aesthetic trend but to demonstrate the broad range of ways African artists have approached photography.","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The journalist''s claim is that Enwezor addressed the neglect of African artists by showing their work within the larger story of global modern art rather than in isolation. <em>Postwar</em> did exactly that, placing Malangatana Ngwenya beside Warhol and Siqueiros.</p><p>Choices A, C, and D are incorrect. Each describes an exhibition devoted to African artists alone, which is the approach the journalist says Enwezor did not rely on.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q15', NULL, 'Reading & Writing', 'Information and Ideas', NULL, 'Inferences', '<p>One challenge when researching whether holding elected office changes a person''s behavior is the problem of ensuring that the experiment has an appropriate control group. To reveal the effect of holding office, researchers must compare people who hold elected office with people who do not hold office but who are otherwise similar to the office-holders. Since researchers are unable to control which politicians win elections, they therefore ______</p><p><strong>Which choice most logically completes the text?</strong></p>', '[{"content":"struggle to find valid data about the behavior of politicians who do not currently hold office.","letter":"A"},{"content":"can only conduct valid studies with people who have previously held office rather than people who presently hold office.","letter":"B"},{"content":"should select a control group of people who differ from office-holders in several significant ways.","letter":"C"},{"content":"will find it difficult to identify a group of people who can function as an appropriate control group for their studies.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. A valid study needs a control group otherwise similar to the office-holders, and researchers cannot control who wins elections, so assembling such a group is difficult.</p><p>Choice A is incorrect. The problem is the composition of the control group, not the availability of data. Choice B is incorrect. The text does not restrict valid studies to former office-holders. Choice C is incorrect. It recommends the opposite of what the text says a control group must be.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q16', NULL, 'Reading & Writing', 'Information and Ideas', NULL, 'Inferences', '<p>Compiled in the late 1500s largely through the efforts of Indigenous scribes, Cantares Mexicanos is the most important collection of poetry in Classical Nahuatl, the principal language of the Aztec Empire. The poems portray Aztec society before the occupation of the empire by the army of Spain, and marginal notes in Cantares Mexicanos indicate that much of the collection''s content <strong>predates the initial invasion</strong>. <strong>Nonetheless</strong>, some of the poems contain <strong>inarguable</strong> references to beliefs and customs common in Spain during this era. Thus, some scholars have concluded that ______</p><p><strong>Which choice most logically completes the text?</strong></p>', '[{"content":"while its content largely predates the invasion, Cantares Mexicanos also contains additions made after the invasion.","letter":"A"},{"content":"although those who compiled Cantares Mexicanos were fluent in Nahuatl, they had limited knowledge of the Spanish language.","letter":"B"},{"content":"before the invasion by Spain, the poets of the Aztec Empire borrowed from the literary traditions of other societies.","letter":"C"},{"content":"the references to beliefs and customs in Spain should be attributed to a coincidental resemblance between the societies of Spain and the Aztec Empire.","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. Two facts are in tension: the marginal notes indicate much of the content predates the invasion, yet some poems refer unmistakably to Spanish beliefs and customs. A collection with an older core and later additions accounts for both.</p><p>Choice B is incorrect. Nothing is said about the compilers'' command of Spanish. Choice C is incorrect. The references are to Spain during the era of the invasion, not to earlier borrowing. Choice D is incorrect. It dismisses the Spanish references rather than accounting for them.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q23', NULL, 'Reading & Writing', 'Standard English Conventions', NULL, 'Boundaries', '<p>The Arctic-Alpine Botanic Garden in Norway and the Jardim Bot&acirc;nico of Rio de Janeiro in Brazil are two of many botanical gardens around the world dedicated to growing diverse plant ______ fostering scientific research<strong>;</strong> and educating the public about plant conservation.</p><p><strong>Which choice completes the text so that it conforms to the conventions of Standard English?</strong></p>', '[{"content":"species, both native and nonnative,","letter":"A"},{"content":"species, both native and nonnative;","letter":"B"},{"content":"species; both native and nonnative,","letter":"C"},{"content":"species both native and nonnative,","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The list has three items and the last two are already separated by a semicolon, so the first break must be a semicolon too. &quot;Both native and nonnative&quot; is a supplementary modifier inside the first item and takes a comma before it.</p><p>Choice A is incorrect. A comma cannot separate items in a series already punctuated with semicolons. Choice C is incorrect. It puts the semicolon inside the first item. Choice D is incorrect. It drops the comma the modifier needs.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q25', NULL, 'Reading & Writing', 'Expression of Ideas', NULL, 'Transitions', '<p>In her poetry collection Thomas and Beulah, Rita Dove interweaves the titular characters'' personal stories with broader historical narratives. She places Thomas''s journey from the American South to the Midwest in the early 1900s within the larger context of the Great Migration. ______ Dove sets events from Beulah''s personal life against the backdrop of the US Civil Rights Movement.</p><p><strong>Which choice completes the text with the most logical transition?</strong></p>', '[{"content":"Specifically,","letter":"A"},{"content":"Thus,","letter":"B"},{"content":"Regardless,","letter":"C"},{"content":"Similarly,","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The second sentence does for Beulah what the first did for Thomas: it sets a personal story against a larger historical movement. &quot;Similarly&quot; marks that parallel.</p><p>Choice A is incorrect. The Beulah example is a second case, not a narrowing of the first. Choice B is incorrect. It is not a consequence. Choice C is incorrect. Nothing is being set aside.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_rw_m2_q27', NULL, 'Reading & Writing', 'Expression of Ideas', NULL, 'Rhetorical Synthesis', '<p>While researching a topic, a student has taken the following notes:</p><ul><li>Astronomers estimate that the number of comets orbiting the Sun is in the billions.</li><li>81P/Wild is one of many comets whose orbit has changed over time.</li><li>81P/Wild''s orbit once lay between the orbits of Uranus and Jupiter.</li><li>The comet''s orbit is now positioned between the orbits of Jupiter and Mars.</li></ul><p><strong>The student wants to make and support a generalization about the orbits of comets. Which choice most effectively uses relevant information from the notes to accomplish these goals?</strong></p>', '[{"content":"Astronomers estimate that the number of comets orbiting the Sun is in the billions; the comets'' orbits may change over time.","letter":"A"},{"content":"Like Uranus, Jupiter, and Mars, billions of comets orbit the Sun.","letter":"B"},{"content":"One example of a comet is 81P/Wild, whose orbit around the Sun once lay between Uranus''s and Jupiter''s orbits but is now positioned between those of Jupiter and Mars.","letter":"C"},{"content":"A comet''s orbit around the Sun may change over time: the orbit of comet 81P/Wild once lay between the orbits of Uranus and Jupiter but is now positioned between those of Jupiter and Mars.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The student wants a generalization about comets'' orbits together with support for it. Choice D states the generalization &mdash; a comet''s orbit may change over time &mdash; and then supports it with the 81P/Wild example.</p><p>Choice A is incorrect. The number of comets does not support a claim about orbits changing. Choice B is incorrect. It makes no claim about change. Choice C is incorrect. It gives the example without stating the generalization.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m1_q20', NULL, 'Math', 'Algebra', NULL, 'Linear inequalities in one or two variables', '<p>The minimum value of <em>x</em> is 12 less than 6 times another number <em>n</em>.</p><p><strong>Which inequality shows the possible values of <em>x</em>?</strong></p>', '[{"content":"x &le; 6n &minus; 12","letter":"A"},{"content":"x &ge; 6n &minus; 12","letter":"B"},{"content":"x &le; 12 &minus; 6n","letter":"C"},{"content":"x &ge; 12 &minus; 6n","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. Twelve less than 6 times n is 6n &minus; 12, and that is the minimum value of x, so x may equal it or be larger: x &ge; 6n &minus; 12.</p><p>Choice A is incorrect. It makes 6n &minus; 12 the maximum rather than the minimum. Choices C and D are incorrect. Both reverse the subtraction, giving 12 &minus; 6n instead of 6n &minus; 12.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m1_q22', NULL, 'Math', 'Algebra', NULL, 'Linear equations in two variables', '<p>The graph of 9<em>x</em> &minus; 10<em>y</em> = 19 is translated down 4 units in the xy-plane.</p><p><strong>What is the x-coordinate of the x-intercept of the resulting graph?</strong></p>', '[]', '["59/9", "6.555", "6.556"]', '<p>The correct answer is 59/9. Translating a graph down 4 units replaces y with y + 4, so 9x &minus; 10(y + 4) = 19, which simplifies to 9x &minus; 10y = 59. At an x-intercept y = 0, so 9x = 59 and x = 59/9. As a decimal that is 6.5555&hellip;, entered as 6.555 truncated or 6.556 rounded.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m2_q4', NULL, 'Math', 'Algebra', NULL, 'Linear equations in two variables', '<figure class="image"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 320" width="420" height="320" role="img" aria-label="An xy-plane. A line slants gradually down from left to right, passing through the points (0, 7) on the y-axis and (8, 0) on the x-axis."><rect width="420" height="320" fill="#fff"/><g stroke="#d6d6dc" stroke-width="1"><line x1="86" y1="30" x2="86" y2="270"/><line x1="122" y1="30" x2="122" y2="270"/><line x1="158" y1="30" x2="158" y2="270"/><line x1="194" y1="30" x2="194" y2="270"/><line x1="230" y1="30" x2="230" y2="270"/><line x1="266" y1="30" x2="266" y2="270"/><line x1="302" y1="30" x2="302" y2="270"/><line x1="338" y1="30" x2="338" y2="270"/><line x1="374" y1="30" x2="374" y2="270"/><line x1="50" y1="240" x2="374" y2="240"/><line x1="50" y1="210" x2="374" y2="210"/><line x1="50" y1="180" x2="374" y2="180"/><line x1="50" y1="150" x2="374" y2="150"/><line x1="50" y1="120" x2="374" y2="120"/><line x1="50" y1="90" x2="374" y2="90"/><line x1="50" y1="60" x2="374" y2="60"/><line x1="50" y1="30" x2="374" y2="30"/></g><line x1="50" y1="270" x2="382" y2="270" stroke="#000" stroke-width="1.5"/><line x1="50" y1="270" x2="50" y2="24" stroke="#000" stroke-width="1.5"/><g font-size="11" font-family="sans-serif" fill="#000"><text x="46" y="286" text-anchor="middle">0</text><text x="122" y="286" text-anchor="middle">2</text><text x="194" y="286" text-anchor="middle">4</text><text x="266" y="286" text-anchor="middle">6</text><text x="338" y="286" text-anchor="middle">8</text><text x="42" y="214" text-anchor="end">2</text><text x="42" y="154" text-anchor="end">4</text><text x="42" y="94" text-anchor="end">6</text><text x="42" y="34" text-anchor="end">8</text><text x="390" y="274" font-style="italic">x</text><text x="44" y="18" font-style="italic">y</text></g><line x1="50" y1="60" x2="338" y2="270" stroke="#000" stroke-width="2"/><circle cx="50" cy="60" r="3.5" fill="#000"/><circle cx="338" cy="270" r="3.5" fill="#000"/><g font-size="11" font-family="sans-serif" fill="#000"><text x="58" y="54">(0, 7)</text><text x="330" y="262" text-anchor="end">(8, 0)</text></g></svg></figure><p>The point with coordinates (<em>d</em>, 4) lies on the line shown.</p><p><strong>What is the value of <em>d</em>?</strong></p>', '[{"content":"7/2","letter":"A"},{"content":"26/7","letter":"B"},{"content":"24/7","letter":"C"},{"content":"27/8","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The line passes through (0, 7) and (8, 0), so its slope is (0 &minus; 7)/(8 &minus; 0) = &minus;7/8 and its equation is y = 7 &minus; (7/8)x. Substituting y = 4 gives (7/8)d = 3, so d = 24/7.</p><p>Choices A, B, and D are incorrect. None satisfies 7 &minus; (7/8)d = 4.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m2_q9', NULL, 'Math', 'Problem-Solving and Data Analysis', NULL, 'Ratios, rates, proportional relationships, and units', '<p>A sample of oak has a density of 807 kilograms per cubic meter. The sample is in the shape of a cube, where each edge has a length of 0.90 meters.</p><p><strong>To the nearest whole number, what is the mass, in kilograms, of this sample?</strong></p>', '[{"content":"588","letter":"A"},{"content":"726","letter":"B"},{"content":"897","letter":"C"},{"content":"1,107","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. The cube''s volume is 0.90&#179; = 0.729 cubic meters, and mass is density times volume: 807 &times; 0.729 = 588.303 kilograms, or 588 to the nearest whole number.</p><p>Choice B is incorrect and results from using 0.90&#178; rather than 0.90&#179;. Choices C and D are incorrect. Both exceed the mass of a 0.729-cubic-meter sample at this density.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m2_q10', NULL, 'Math', 'Advanced Math', NULL, 'Nonlinear functions', '<p style="font-family:serif;font-size:18px"><em>P</em>(<em>t</em>) = 290(1.04)<sup>(4/6)<em>t</em></sup></p><p>The function <em>P</em> models the population, in thousands, of a certain city <em>t</em> years after 2005. According to the model, the population is predicted to increase by <em>n</em>% every 18 months.</p><p><strong>What is the value of <em>n</em>?</strong></p>', '[{"content":"0.38","letter":"A"},{"content":"1.04","letter":"B"},{"content":"4","letter":"C"},{"content":"6","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. Eighteen months is 1.5 years, and substituting t = 1.5 makes the exponent (4/6)(1.5) = 1. Over any 18-month stretch the population is therefore multiplied by 1.04, an increase of 4%, so n = 4.</p><p>Choice A is incorrect and may come from misreading the exponent. Choice B is incorrect. 1.04 is the growth factor, not the percent increase. Choice D is incorrect. 6 is part of the exponent, not the rate.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m2_q12', NULL, 'Math', 'Problem-Solving and Data Analysis', NULL, 'Percentages', '<p>A gift shop buys souvenirs at a wholesale price of $7.00 each and resells them each at a retail price that is 290% of the wholesale price. At the end of the season, any remaining souvenirs are marked at a discounted price that is <strong>80% off</strong> the retail price.</p><p><strong>What is the discounted price of each remaining souvenir, in dollars?</strong></p>', '[]', '["203/50", "4.06"]', '<p>The correct answer is 4.06. The retail price is 290% of $7.00, or $20.30. Marking that down by 80% leaves 20% of it, and 0.20 &times; 20.30 = $4.06. The value may also be entered as 203/50.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m2_q13', NULL, 'Math', 'Advanced Math', NULL, 'Nonlinear equations in one variable', '<p style="font-family:serif;font-size:18px"><em>x</em>&sup2; &minus; 34<em>x</em> + <em>c</em> = 0</p><p>In the given equation, <em>c</em> is a constant. The equation has no real solutions if <em>c</em> &gt; <em>n</em>.</p><p><strong>What is the least possible value of <em>n</em>?</strong></p>', '[]', '["289"]', '<p>The correct answer is 289. A quadratic equation has no real solutions exactly when its discriminant is negative. Here b&#178; &minus; 4ac = (&minus;34)&#178; &minus; 4c = 1,156 &minus; 4c, and 1,156 &minus; 4c &lt; 0 gives c &gt; 289. So the least possible value of n is 289.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt4_math_m2_q19', NULL, 'Math', 'Advanced Math', NULL, 'Nonlinear equations in one variable', '<p style="font-family:serif;font-size:18px">57<em>x</em>&sup2; + (57<em>b</em> + <em>a</em>)<em>x</em> + <em>ab</em> = 0</p><p>In the given equation, <em>a</em> and <em>b</em> are positive constants. The product of the solutions to the given equation is <em>k</em>&middot;<em>ab</em>, where <em>k</em> is a constant.</p><p><strong>What is the value of <em>k</em>?</strong></p>', '[{"content":"1/57","letter":"A"},{"content":"1/19","letter":"B"},{"content":"1","letter":"C"},{"content":"57","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. For a quadratic equation ax&#178; + bx + c = 0, the product of the solutions is c/a. Here that product is ab/57, which is (1/57) &middot; ab, so k = 1/57.</p><p>Choices B, C, and D are incorrect. Each would require a leading coefficient other than 57.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q2', NULL, 'Reading & Writing', 'Craft and Structure', 'Hard', 'Words in Context', '<p>In 1891, design artist William Morris cofounded the Kelmscott Press, which printed editions of books using preindustrial methods. Historians argue that Morris''s repudiation of industrialization is ______ the Kelmscott editions'' use of handmade materials and intricate ornamentation reminiscent of medieval manuscripts: these meticulously handcrafted elements exemplify the artistry involved.</p><p><strong>Which choice completes the text with the most logical and precise word or phrase?</strong></p>', '[{"content":"insensible to","letter":"A"},{"content":"manifest in","letter":"B"},{"content":"scrutinized by","letter":"C"},{"content":"complicated by","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The colon introduces the evidence &mdash; handmade materials and medieval-style ornament &mdash; that shows where Morris''s rejection of industrialization can be seen. &quot;Manifest in&quot; means plainly shown by.</p><p>Choices A and D are incorrect. Both reverse the relation the colon sets up. Choice C is incorrect. The Kelmscott editions display the repudiation rather than examine it.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q3', NULL, 'Reading & Writing', 'Craft and Structure', 'Hard', 'Words in Context', '<p>______ the long-standing trend of overemphasizing teenagers and young adults in research on social media use, scholars have recently begun to expand their focus to include the fastest-growing cohort of social media users: senior citizens.</p><p><strong>Which choice completes the text with the most logical and precise word or phrase?</strong></p>', '[{"content":"Exacerbating","letter":"A"},{"content":"Redressing","letter":"B"},{"content":"Epitomizing","letter":"C"},{"content":"Precluding","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. Scholars are correcting a long-standing overemphasis by widening their focus to senior citizens. &quot;Redressing&quot; means setting right.</p><p>Choices A and C are incorrect. Both would mean continuing the imbalance rather than correcting it. Choice D is incorrect. &quot;Precluding&quot; would mean preventing a trend that has already taken hold.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q4', NULL, 'Reading & Writing', 'Craft and Structure', 'Hard', 'Words in Context', '<p>Adapted from James Baldwin''s 1956 novel Giovanni''s Room. The narrator is riding in a taxi down a street lined with food vendors and shoppers in Paris. "The multitude of Paris... Here they were now, in blue, disputing, every inch, our passage, with their wagons, handtrucks, their bursting baskets..."</p><p><strong>As used in the text, what does the word "disputing" most nearly mean?</strong></p>', '[{"content":"Arguing about","letter":"A"},{"content":"Disapproving of","letter":"B"},{"content":"Asserting possession of","letter":"C"},{"content":"Providing resistance to","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The wagons, handtrucks, and baskets are physically in the taxi''s way, contesting &quot;every inch&quot; of its passage &mdash; that is, providing resistance to it.</p><p>Choices A and B are incorrect. Both take the word in its verbal sense, but nothing is being argued about. Choice C is incorrect. The crowd is obstructing the street rather than claiming ownership of it.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q6', NULL, 'Reading & Writing', 'Craft and Structure', 'Hard', 'Text Structure and Purpose', '<p>Scholarly accounts of the Chicano movement tend to focus on the most militant, outspoken figures, making it seem uniformly radical. Geographer Juan Herrera has shown that shifting focus to low-profile neighborhood institutions reveals participants espousing an array of political orientations.</p><p><strong>Which choice best describes the function of the underlined portion in the text as a whole?</strong></p>', '[{"content":"Presents a trend the text claims has been reevaluated by researchers.","letter":"A"},{"content":"Identifies an aspect overemphasized due to scholars'' own political orientations.","letter":"B"},{"content":"Describes a common approach that obscures the ideological diversity of participants.","letter":"C"},{"content":"Summarizes the conventional method, which the text suggests misrepresents effectiveness of neighborhood projects.","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The underlined portion describes the usual scholarly focus on the most militant figures and notes that it makes the movement look uniformly radical; Herrera''s work then reveals a range of political orientations that the usual focus had hidden.</p><p>Choice A is incorrect. The text shows the approach is misleading rather than that it has been reevaluated. Choice B is incorrect. The scholars'' own politics are not at issue. Choice D is incorrect. The contrast is about ideological diversity, not effectiveness.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q12', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<p>Under normal atmospheric pressure, water molecules form a tetrahedral network stabilized by hydrogen bonds. Extreme pressure destabilizes these bonds; piezophiles have adapted to it. Studies found a positive correlation between depth and TMAO concentration, leading researchers to hypothesize TMAO reduces water''s compressibility.</p><p><strong>Which finding, if true, would most directly support the researchers'' hypothesis?</strong></p>', '[{"content":"Water molecules are impervious to TMAO even when distorted by high pressure.","letter":"A"},{"content":"TMAO retains its molecular shape as pressure increases.","letter":"B"},{"content":"A positive correlation between TMAO concentration and the rate water''s structure compresses as pressure increases.","letter":"C"},{"content":"Hydrogen bonds are more stable when TMAO is present than when it is not.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The hypothesis is that TMAO reduces water''s compressibility, and the passage explains that water compresses under pressure because its hydrogen-bond network is destabilized. Hydrogen bonds holding up better with TMAO present supplies exactly that mechanism.</p><p>Choice C is incorrect. It describes a correlation in the wrong direction. Choices A and B are incorrect. Both concern TMAO''s own behavior rather than its effect on water.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q13', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<p>Persad and colleagues modeled what happens to irrigation when a region''s yearly precipitation becomes concentrated into fewer, heavier events. Where the baseline precipitation was already somewhat concentrated, the model showed aquifer input rising 4.9%, surface irrigation rising 0.4%, and groundwater irrigation rising 0.9%. Where the baseline precipitation had been evenly distributed, surface irrigation rose 9.0% and groundwater irrigation rose 7.9%. The researchers concluded that concentrating precipitation triggers more irrigation, but that the size of the change is highly sensitive to how concentrated the baseline precipitation already was.</p><p><strong>Which choice best describes data that support Persad and colleagues'' conclusion?</strong></p>', '[{"content":"Compares irrigation change to aquifer change.","letter":"A"},{"content":"If somewhat concentrated, irrigation increases only slightly; if evenly distributed, 9.0%/7.9%.","letter":"B"},{"content":"If somewhat concentrated, aquifer +4.9%, irrigation +0.4%/+0.9%.","letter":"C"},{"content":"Claims irrigation use will decline.","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The conclusion has two parts: concentrating precipitation increases irrigation, and the size of that increase depends heavily on the baseline. Choice B gives both, contrasting the slight rise where precipitation was already somewhat concentrated with the 9.0% and 7.9% rises where it had been evenly distributed.</p><p>Choice A is incorrect. Comparing irrigation with aquifer input says nothing about sensitivity to the baseline. Choice C is incorrect. It reports only one baseline, so it cannot show a difference between them. Choice D is incorrect. It contradicts the conclusion.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q16', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Boundaries', '<p>Consider the mechanics of the pinhole camera: light passes through a small hole, resulting in a focused projected image. A ray diagram reveals how this ______ the hole''s small size restricts light to a single ray, all light passing through can only arrive at a single destination, eliminating diffraction and ensuring a clear image.</p><p><strong>Which choice completes the text so that it conforms to the conventions of Standard English?</strong></p>', '[{"content":"works because","letter":"A"},{"content":"works. Because","letter":"B"},{"content":"works, it''s because","letter":"C"},{"content":"works: it''s because","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. &quot;A ray diagram reveals how this works&quot; is a complete sentence, and choice B ends it with a period and opens the next with &quot;Because&quot;, which turns &quot;the hole''s small size restricts light to a single ray&quot; into a subordinate clause attached to &quot;all light passing through can only arrive at a single destination&quot;.</p><p>Choices A, C, and D are incorrect. Each leaves &quot;the hole''s small size restricts light to a single ray&quot; and &quot;all light passing through can only arrive at a single destination&quot; as two independent clauses joined by only a comma.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q18', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Boundaries', '<p>In 1986, conceptual artist Sophie Calle asked twenty-three people, all born without sight, to describe "their image of beauty." Calle paired excerpts of these conversations with photographs—both of interviewees and the items they ______ to powerful effect in her exhibition The Blind.</p><p><strong>Which choice completes the text so that it conforms to the conventions of Standard English?</strong></p>', '[{"content":"described, from hair to grass to sculptures","letter":"A"},{"content":"described, from hair to grass to sculptures—","letter":"B"},{"content":"described—from hair to grass to sculptures,","letter":"C"},{"content":"described: from hair to grass to sculptures","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The sentence opens an aside with the dash after &quot;photographs&quot;, and an aside marked that way has to be closed with a matching dash before the sentence resumes at &quot;to powerful effect&quot;.</p><p>Choice A is incorrect. It never closes the aside. Choice C is incorrect. It puts a dash inside the aside rather than at its end. Choice D is incorrect. A colon cannot close a dash-marked aside.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q19', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Form, Structure, and Sense', '<p>American abstract artist Richard ______ his installations to make passersby keenly aware of how one''s movements are affected by the physical features of one''s environment, assembles large-scale steel plates into sculptures that dominate the outdoor spaces they occupy.</p><p><strong>Which choice completes the text so that it conforms to the conventions of Standard English?</strong></p>', '[{"content":"Serra is intending","letter":"A"},{"content":"Serra, intends","letter":"B"},{"content":"Serra, intending","letter":"C"},{"content":"Serra intends","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The main clause is &quot;Richard Serra &hellip; assembles large-scale steel plates into sculptures&quot;. Between the subject and that verb sits a modifying phrase, which needs a participle and a comma at each end.</p><p>Choices A and D are incorrect. Each gives the sentence a second finite verb. Choice B is incorrect. &quot;Intends&quot; is finite, so the material between the commas becomes a clause rather than a modifier.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q20', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Form, Structure, and Sense', '<p>A species of Byropsis algae produces toxins to avoid being eaten by predators. However, in some cases, the toxins the organism uses to protect itself from predation actually ______ its attractiveness to predators.</p><p><strong>Which choice completes the text so that it conforms to the conventions of Standard English?</strong></p>', '[{"content":"is increasing","letter":"A"},{"content":"increase","letter":"B"},{"content":"increases","letter":"C"},{"content":"has increased","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The subject of the blank is the plural &quot;toxins&quot;, and the sentence is in the present tense, so the verb is &quot;increase&quot;.</p><p>Choices A and C are incorrect. Both are singular. Choice D is incorrect. It is singular and shifts to the present perfect.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q23', NULL, 'Reading & Writing', 'Expression of Ideas', 'Hard', 'Transitions', '<p>In hindsight, given the ideas circulating among British scientists in the 1800s, the theory of natural selection was an obvious next step. It may not have been a coincidence, ______ that Charles Darwin and Alfred Wallace arrived at the concept independently.</p><p><strong>Which choice completes the text with the most logical transition?</strong></p>', '[{"content":"however,","letter":"A"},{"content":"then,","letter":"B"},{"content":"moreover,","letter":"C"},{"content":"for example,","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The first sentence says the theory was, in hindsight, an obvious next step; the second draws the inference that Darwin and Wallace arriving at it independently may be no coincidence. &quot;Then&quot; marks that inference.</p><p>Choice A is incorrect. The two sentences agree rather than contrast. Choice C is incorrect. The second sentence follows from the first rather than adding to it. Choice D is incorrect. It is not an example.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q24', NULL, 'Reading & Writing', 'Expression of Ideas', 'Hard', 'Transitions', '<p>In a recent study, researchers examined sleeping/waking habits of dairy cows to determine if they were diurnal, nocturnal, or crepuscular. ______ the researchers studied whether the cows were most active in daytime, nighttime, or at dawn/dusk.</p><p><strong>Which choice completes the text with the most logical transition?</strong></p>', '[{"content":"Afterward,","letter":"A"},{"content":"In other words,","letter":"B"},{"content":"Additionally,","letter":"C"},{"content":"However,","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The second sentence restates &quot;diurnal, nocturnal, or crepuscular&quot; in plain terms &mdash; daytime, nighttime, or dawn and dusk. &quot;In other words&quot; marks a restatement.</p><p>Choices A, C, and D are incorrect. Nothing follows in sequence, nothing is added, and nothing is contrasted; the same idea is simply put differently.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_rw_m2_q26', NULL, 'Reading & Writing', 'Expression of Ideas', 'Hard', 'Rhetorical Synthesis', '<p>Student notes: FWS lists species as endangered or threatened; endangered = danger of extinction throughout most/all range; threatened = likely to soon become endangered; the California red-legged frog is likely to soon become endangered per FWS.</p><p><strong>The student wants to indicate the frog''s FWS classification category. Which choice most effectively uses relevant information from the notes to accomplish this goal?</strong></p>', '[{"content":"Species on the FWS list, which includes the frog, are classified as either endangered or threatened.","letter":"A"},{"content":"The frog appears on the FWS list of at-risk species.","letter":"B"},{"content":"The frog is in the endangered category, in danger of extinction throughout most or all of its range.","letter":"C"},{"content":"Likely to soon become endangered, the frog is classified as threatened by the FWS.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The notes define &quot;threatened&quot; as likely to soon become endangered and state that the frog is likely to soon become endangered, so the frog''s category is threatened.</p><p>Choice C is incorrect. It names the wrong category. Choices A and B are incorrect. Neither states which category the frog falls into.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_math_m2_q8', NULL, 'Math', 'Algebra', 'Hard', 'Linear functions', '<div class="qtable"><table><tr><th>Number of cars, <em>c</em></th><th>Maximum number of passengers and crew, <em>p</em></th></tr><tr><td>3</td><td>174</td></tr><tr><td>5</td><td>284</td></tr><tr><td>10</td><td>559</td></tr></table></div><p>The table shows three values of <em>c</em> and their corresponding values of <em>p</em>. There is a linear relationship between <em>c</em> and <em>p</em>.</p><p><strong>Which equation represents the linear relationship between c and p?</strong></p>', '[{"content":"55c − p = −9","letter":"A"},{"content":"55c − p = 9","letter":"B"},{"content":"55p − c = 9","letter":"C"},{"content":"55p − c = −9","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. From c = 3 to c = 5, p rises from 174 to 284, a slope of 110/2 = 55. Then 174 = 55(3) + b gives b = 9, so p = 55c + 9, which rearranges to 55c &minus; p = &minus;9. The third row checks: c = 10 gives p = 559.</p><p>Choice B is incorrect. It gives p = 55c &minus; 9, which fails at every row. Choices C and D are incorrect. Both swap c and p, treating the number of cars as the dependent quantity.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_math_m2_q16', NULL, 'Math', 'Problem-Solving and Data Analysis', 'Hard', 'Probability and conditional probability', '<p>6 rows of birch trees (8 tall/6 short per row), 5 rows of maple trees (9 tall/7 short per row). A tree is selected at random.</p><p><strong>What is the probability of selecting a maple tree, given that it is 20 feet or taller?</strong></p>', '[{"content":"9/164","letter":"A"},{"content":"3/10","letter":"B"},{"content":"15/31","letter":"C"},{"content":"9/17","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The condition &quot;20 feet or taller&quot; restricts the count to tall trees only. There are 6 &times; 8 = 48 tall birches and 5 &times; 9 = 45 tall maples, so 93 tall trees in all, and the conditional probability of a maple is 45/93 = 15/31.</p><p>Choice A is incorrect. It divides by the total number of trees rather than by the number of tall trees. Choices B and D are incorrect. Neither is the ratio of tall maples to all tall trees.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_math_m2_q17', NULL, 'Math', 'Geometry and Trigonometry', 'Hard', 'Right triangles and trigonometry', '<p>A rectangle is inscribed in a circle (each vertex on the circle). The diagonal is twice the length of the shortest side. The area of the rectangle is 1,089√3 square units.</p><p><strong>What is the length, in units, of the diameter of the circle?</strong></p>', '[]', '["66"]', '<p>The correct answer is 66. Let s be the shortest side. The diagonal is 2s, so the right triangle formed by the two sides and the diagonal is a 30-60-90 triangle and the longer side is s&radic;3. The area is s &middot; s&radic;3 = s&#178;&radic;3 = 1,089&radic;3, so s&#178; = 1,089 and s = 33. A diagonal of a rectangle inscribed in a circle is a diameter, so the diameter is 2s = 66.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_math_m2_q19', NULL, 'Math', 'Algebra', 'Hard', 'Systems of two linear equations in two variables', '<p>System: (7/8)y − (5/8)x = 4/7 − (7/8)y, and (5/4)x + 7/4 = py + 15/4, where p is a constant.</p><p><strong>If the system has no solution, what is the value of p?</strong></p>', '[]', '["3.5","7/2"]', '<p>The correct answer is 7/2. Collecting the y terms in the first equation gives (7/4)y &minus; (5/8)x = 4/7; multiplying by &minus;2 gives (5/4)x &minus; (7/2)y = &minus;8/7. The second equation rearranges to (5/4)x &minus; py = 2. The x-coefficients already match and the constants differ, so the system has no solution exactly when the y-coefficients match as well: p = 7/2, which may also be entered as 3.5.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_math_m2_q20', NULL, 'Math', 'Advanced Math', 'Hard', 'Nonlinear functions', '<div class="qtable"><table><tr><th><em>x</em></th><th><em>g</em>(<em>x</em>)</th></tr><tr><td>&minus;27</td><td>3</td></tr><tr><td>&minus;9</td><td>0</td></tr><tr><td>5</td><td>7</td></tr></table></div><p>The table shows three values of <em>x</em> and their corresponding values of <em>g</em>(<em>x</em>), where <em>g</em>(<em>x</em>) = <em>f</em>(<em>x</em>)/(<em>x</em> + 3) and <em>f</em> is a linear function.</p><p><strong>What is the y-intercept of the graph of y = f(x)?</strong></p>', '[{"content":"(0, 36)","letter":"A"},{"content":"(0, 12)","letter":"B"},{"content":"(0, 4)","letter":"C"},{"content":"(0, −9)","letter":"D"}]', '["A"]', '<p>Choice A is the best answer. Since g(x) = f(x)/(x + 3), f(x) = g(x)(x + 3). The table gives f(&minus;27) = 3(&minus;24) = &minus;72 and f(&minus;9) = 0(&minus;6) = 0. A line through (&minus;27, &minus;72) and (&minus;9, 0) has slope 72/18 = 4, so f(x) = 4(x + 9) = 4x + 36 and the y-intercept is (0, 36). The third row checks: f(5) = 56 and g(5) = 56/8 = 7.</p><p>Choices B, C, and D are incorrect. None gives a linear f that produces the values of g in the table.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt6_math_m2_q21', NULL, 'Math', 'Geometry and Trigonometry', 'Hard', 'Circles', '<p>Circle center G, points M and N on the circle. Segments MH and NH are tangent to the circle at M and N. Radius = 168 mm, perimeter of quadrilateral GMHN = 3,856 mm.</p><p><strong>What is the distance, in millimeters, between points G and H?</strong></p>', '[{"content":"168","letter":"A"},{"content":"1,752","letter":"B"},{"content":"1,760","letter":"C"},{"content":"1,768","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. A tangent meets the radius at its point of tangency at a right angle, and the two tangent segments drawn from H are equal. The perimeter of GMHN is 168 + MH + NH + 168 = 3,856, so MH = NH = 1,760. In right triangle GMH, GH = &radic;(168&#178; + 1,760&#178;) = &radic;3,125,824 = 1,768.</p><p>Choice A is incorrect. That is the radius. Choice B is incorrect and results from subtracting rather than applying the Pythagorean theorem. Choice C is incorrect. That is the length of a tangent segment, not GH.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q25', NULL, 'Reading & Writing', 'Expression of Ideas', 'Hard', 'Rhetorical Synthesis', '<p><strong>Notes:</strong> Norway''s Storting (169 seats) awards seats by a formula weighting land area (1.8 pts/unit) over population (1 pt/resident) — so less-populated rural districts get disproportionately more seats than smaller, more populated urban districts.</p><p><strong>Student wants to refute the claim that malapportionment in the Storting favors small urban districts. Which choice best does this using the notes?</strong></p>', '[{"content":"Rural districts are underrepresented, creating an unfair advantage for smaller but more populated urban districts.","letter":"A"},{"content":"It''s untrue that malapportionment favors small urban districts; rather, the formula overrepresents more populated districts.","letter":"B"},{"content":"Malapportionment occurs when districts are over/underrepresented.","letter":"C"},{"content":"Awarding more points per land unit than per resident, the formula overrepresents less populated rural districts.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. To refute the claim that malapportionment favors small urban districts, the student needs the notes'' central fact: the formula weights land area more heavily than residents, so it is the less populated rural districts that gain seats.</p><p>Choice A is incorrect. It gets the direction backwards. Choice B is incorrect. It contradicts the notes by saying the more populated districts are overrepresented. Choice C is incorrect. It only defines the term.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q10', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<p>Sea otters damage eelgrass roots while digging for clams. Near Vancouver Island, eelgrass meadows are healthier than elsewhere despite a large otter population. Foster hypothesized: root damage → increased sexual reproduction → more genetic diversity → healthier meadows.</p><p><strong>Which finding, if true, would most directly undermine Foster''s hypothesis?</strong></p>', '[{"content":"Some sites have small, recently-reintroduced otter populations near eelgrass meadows.","letter":"A"},{"content":"Some sites without the study have large otter populations but no eelgrass meadows at all.","letter":"B"},{"content":"At sites not in the study, meadow health correlates negatively with otter population size/residence length.","letter":"C"},{"content":"At some sites, unrelated (non-eelgrass) plant health correlates negatively with otter population size/residence.","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. Foster''s hypothesis is that otter digging ultimately improves meadow health. A finding at other sites that meadow health falls as otter numbers and length of residence rise points the other way.</p><p>Choice A is incorrect. Recently reintroduced populations say nothing about the long-run effect. Choice B is incorrect. Sites with no meadows offer nothing to compare. Choice D is incorrect. It concerns plants other than eelgrass.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q22', NULL, 'Reading & Writing', 'Expression of Ideas', 'Hard', 'Transitions', '<p>A viewer of Kurt Wenner''s street painting <em>Dies Irae</em> might assume a real hole with sculptures has opened in the street. ______ By expertly using perspective, Wenner created merely the illusion of depth.</p><p><strong>Which choice completes the text with the most logical transition?</strong></p>', '[{"content":"Additionally,","letter":"A"},{"content":"On the contrary,","letter":"B"},{"content":"As a result,","letter":"C"},{"content":"Next,","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The first sentence gives what a viewer might assume &mdash; that a real hole has opened in the street &mdash; and the second corrects it: the depth is only an illusion. &quot;On the contrary&quot; marks that correction.</p><p>Choices A and D are incorrect. Both would continue rather than contradict. Choice C is incorrect. The illusion is not a result of the viewer''s assumption.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m1_q14', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Inferences', '<p>Excavations at Kuulo Kataa (Ghana) turned up some artifacts dating to the 13th century CE, but other evidence strongly supports a 14th-century CE founding date for the settlement.</p><p><strong>If both the artifact dates and the 14th-century founding date are correct, that would imply that:</strong></p>', '[{"content":"14th-century artifacts are more commonly recovered than 13th-century artifacts.","letter":"A"},{"content":"the artifacts originated elsewhere and eventually reached Kuulo Kataa through trade or migration.","letter":"B"},{"content":"Kuulo Kataa was founded by people from a different region than had previously been assumed.","letter":"C"},{"content":"excavations may have inadvertently damaged some 14th-century artifacts.","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. If the settlement was founded in the fourteenth century, thirteenth-century artifacts cannot have been made there, so they must have originated elsewhere and arrived later.</p><p>Choice A is incorrect. The relative frequency of artifacts is not at issue. Choice C is incorrect. Nothing follows about where the founders came from. Choice D is incorrect. Damage to later artifacts would not explain the presence of earlier ones.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q12', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<p>In an experiment, flies whose <em>DptA</em> gene was silenced (type A) stayed near 90% survival after infection with <em>A. sicerae</em>, while flies whose <em>DptB</em> gene was silenced &mdash; alone (type B) or together with <em>DptA</em> (type AB) &mdash; dropped to near 0% survival. Separately, it is <em>DptA</em> activity, not <em>DptB</em>, that correlates with resistance to a different bacterium, <em>P. rettgeri</em>.</p><p><strong>Which choice most logically completes the statement about what these data suggest?</strong></p>', '[{"content":"DptA confers defense against A. sicerae regardless of DptB''s presence.","letter":"A"},{"content":"DptB protects against only one bacteria species, whereas DptA protects against multiple.","letter":"B"},{"content":"DptB may have developed as a specific defense against A. sicerae.","letter":"C"},{"content":"Defense against A. sicerae is strongest when both DptA and DptB are present.","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. Silencing DptA alone left survival near 90%, while silencing DptB &mdash; with or without DptA &mdash; dropped it to near zero, so it is DptB that defends against <em>A. sicerae</em>. Since DptA, not DptB, is the gene tied to resistance against <em>P. rettgeri</em>, DptB looks like a defense specific to <em>A. sicerae</em>.</p><p>Choice A is incorrect. It credits DptA, which the type A flies show is not needed. Choice B is incorrect. It reverses which gene is the specialist. Choice D is incorrect. DptB alone is sufficient, so both genes are not required.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q14', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Inferences', '<p>Sea stars (radially symmetric) evolved from bilateral ancestors, previously assumed to have lost their "head" region. Gene-marker comparison with a close bilateral relative showed: anterior ("head") genes active across the ENTIRE sea star body; posterior ("tail") genes active only at the edges; no trunk genes active at all.</p><p><strong>These findings suggest that:</strong></p>', '[{"content":"Posterior genes at the body''s edge are primarily responsible for sea stars'' starlike layout, despite anterior genes'' greater prevalence.","letter":"A"},{"content":"Sea stars'' body plan is neither bilaterally nor radially symmetrical, contrary to assumed bilateral ancestry.","letter":"B"},{"content":"There''s only minimal correspondence between the sea star and its relative''s genetic markers for head/tail/trunk.","letter":"C"},{"content":"Rather than losing a head region, sea stars'' morphology evolved to consist almost entirely of a head region, with no trunk.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. Head genes are active across the entire body, tail genes only at the edges, and trunk genes not at all. That describes an animal that is almost entirely head rather than one that lost its head.</p><p>Choice A is incorrect. It credits the posterior genes for the body plan. Choice B is incorrect. The sea star''s radial symmetry is not in question. Choice C is incorrect. The markers correspond closely; it is their distribution that is surprising.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q11', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Command of Evidence', '<p>Espinosa argues Mexican American folklore derives mainly from Spain (which ruled the region for centuries). Paredes argues it''s mainly the product of ongoing cultural interactions in Mexico/the US, not Spanish origin.</p><p><strong>Which finding, if true, would most directly support Paredes''s argument?</strong></p>', '[{"content":"Collected folklore included songs in a 16th-century Spanish poetic form (decima).","letter":"A"},{"content":"Much of the folklore had similar elements across different regions.","letter":"B"},{"content":"Most of the folklore was previously unknown to scholars.","letter":"C"},{"content":"Most of the folklore consisted of ballads (corridos) of clearly recent origin.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. Paredes holds that the folklore is mainly the product of ongoing cultural interaction rather than inherited from Spain, and folklore consisting largely of ballads of clearly recent origin is exactly that.</p><p>Choice A is incorrect. A sixteenth-century Spanish form supports Espinosa instead. Choices B and C are incorrect. Neither shared elements across regions nor unfamiliarity to scholars bears on where the folklore came from.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m1_q19', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Boundaries', '<p>Gil Scott-Heron resisted the "godfather of rap" nickname ______ feeling it didn''t capture his devotion to the blues tradition as well as his preferred term, "bluesologist."</p><p><strong>Which choice completes the text so it conforms to Standard English conventions?</strong></p>', '[{"content":"nickname, however","letter":"A"},{"content":"nickname, however;","letter":"B"},{"content":"nickname, however,","letter":"C"},{"content":"nickname; however,","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. &quot;However&quot; interrupts the sentence and takes a comma on each side, and what follows is a participial phrase rather than an independent clause.</p><p>Choice A is incorrect. It omits the comma after &quot;however&quot;. Choices B and D are incorrect. A semicolon must be followed by an independent clause, and &quot;feeling &hellip;&quot; is not one.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q19', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Boundaries', '<p>John Donne''s works, much ______ during his lifetime (1572-1631) and after, had — by the time of their rediscovery by early-20th-century modernists — been gathering dust for 250 years.</p><p><strong>Which choice completes the text so it conforms to Standard English conventions?</strong></p>', '[{"content":"works were","letter":"A"},{"content":"works, were","letter":"B"},{"content":"works, admired,","letter":"C"},{"content":"works had been","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. &quot;Much admired during his lifetime and after&quot; is a supplementary phrase describing Donne''s works and needs a comma at each end, leaving &quot;John Donne''s works &hellip; had been gathering dust&quot; as the main clause.</p><p>Choices A and D are incorrect. Each supplies a second finite verb. Choice B is incorrect. It opens the phrase with a comma but never closes it, and leaves &quot;were&quot; as a competing verb.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m1_q16', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Form, Structure, and Sense', '<p>ASEAN was formed in 1967 with five members. By the end of the 1990s, the organization ______ its initial membership.</p><p><strong>Which choice completes the text so it conforms to Standard English conventions?</strong></p>', '[{"content":"has doubled","letter":"A"},{"content":"had doubled","letter":"B"},{"content":"doubles","letter":"C"},{"content":"will double","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. The doubling was complete by the end of the 1990s, a point already in the past, so the past perfect &quot;had doubled&quot; is required.</p><p>Choice A is incorrect. The present perfect ties the action to the present. Choice C is incorrect. It is present tense. Choice D is incorrect. It is future tense.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_math_m2_q16', NULL, 'Math', 'Problem-Solving and Data Analysis', 'Hard', 'Percentages', '<p>A shirt''s regular price is $11.70. The sale price is 80% less than regular. The sale price is also 30% greater than the store''s cost.</p><p><strong>What is the store''s cost, in dollars?</strong></p>', '[]', '["1.8", "9/5"]', '<p>The correct answer is 1.8. A price 80% less than $11.70 is 20% of it: 0.20 &times; 11.70 = $2.34. That sale price is 30% greater than the store''s cost, so 1.30 &times; cost = 2.34 and the cost is $1.80. The value may also be entered as 9/5.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_math_m2_q22', NULL, 'Math', 'Problem-Solving and Data Analysis', 'Hard', 'Inference from sample statistics and margin of error', '<p>Poll of 803 voters: Angel Cruz 483, Terry Smith 320. Projected to a total of 6,424 voters in the actual election.</p><p><strong>By how many votes would Angel Cruz be expected to win?</strong></p>', '[{"content":"163","letter":"A"},{"content":"1,304","letter":"B"},{"content":"3,864","letter":"C"},{"content":"5,621","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. In the poll Cruz leads by 483 &minus; 320 = 163 votes out of 803. The election is projected at 6,424 voters, which is 6,424/803 = 8 times as many, so the projected margin is 163 &times; 8 = 1,304 votes.</p><p>Choice A is incorrect. That is the margin in the poll, not the projection. Choice C is incorrect. 3,864 is Cruz''s projected total, not his margin. Choice D is incorrect. It is not supported by the poll''s proportions.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_math_m2_q17', NULL, 'Math', 'Geometry and Trigonometry', 'Hard', 'Lines, angles, and triangles', '<p>Triangles ABC and DEF: angle B = angle E = 27 degrees, angle C = angle F = 41 degrees (so the triangles are already known to be similar, by AA).</p><p><strong>Which additional piece of information is sufficient to determine whether triangle ABC is congruent to triangle DEF?</strong></p>', '[{"content":"The measure of angle A.","letter":"A"},{"content":"The length of side AB.","letter":"B"},{"content":"The lengths of sides BC and EF.","letter":"C"},{"content":"No additional information is necessary.","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The triangles already share two pairs of congruent angles, so they are similar; what is missing is any information about size. A pair of corresponding sides fixes the scale factor and so settles whether the triangles are congruent.</p><p>Choice A is incorrect. The third angle follows from the two already given, so it adds nothing. Choice B is incorrect. A side of one triangle alone cannot be compared with the other. Choice D is incorrect. Similar triangles need not be congruent.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q7', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Central Ideas and Details', '<p>In Lewis Carroll''s <em>Sylvie and Bruno</em>, a crowd shouts different, contradictory things ("Bread!", "Taxes!") outside a window. The Lord Chancellor watches and repeats, "What can it all mean? ...And with such unanimity!"</p><p><strong>Based on the text, how does the Lord Chancellor respond to the crowd?</strong></p>', '[{"content":"He asks about the meaning of the shouting, even though he claims to know what the crowd wants.","letter":"A"},{"content":"He indicates a desire to speak to the crowd, even though the crowd asked to speak to the Sub-Warden.","letter":"B"},{"content":"He expresses sympathy for the crowd''s demands, even though the shouting annoys him.","letter":"C"},{"content":"He describes the crowd as united, even though the crowd clearly is not.","letter":"D"}]', '["D"]', '<p>Choice D is the best answer. The crowd shouts contradictory demands, yet the Lord Chancellor remarks on their &quot;unanimity&quot; &mdash; he describes as united a crowd that plainly is not.</p><p>Choice A is incorrect. He asks what it means rather than claiming to know. Choices B and C are incorrect. He expresses neither a wish to address the crowd nor sympathy for its demands.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q15', NULL, 'Reading & Writing', 'Standard English Conventions', 'Hard', 'Form, Structure, and Sense', '<p>Interest in mechanotransduction is expanding because of biomedical scientists — many of whom, like [neuroscientist] Elba Serrano, ______ this mechanism to better understand neurological/biomechanical interaction.</p><p><strong>Which choice completes the text so it conforms to Standard English conventions?</strong></p>', '[{"content":"is studying","letter":"A"},{"content":"has studied","letter":"B"},{"content":"study","letter":"C"},{"content":"studies","letter":"D"}]', '["C"]', '<p>Choice C is the best answer. The verb belongs to &quot;many of whom&quot;, which refers to the plural &quot;scientists&quot;, so the plural &quot;study&quot; is required.</p><p>Choices A and D are incorrect. Both are singular. Choice B is incorrect. It is singular and shifts the tense away from the ongoing work the sentence describes.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_math_m2_q20', NULL, 'Math', 'Geometry and Trigonometry', 'Hard', 'Right triangles and trigonometry', '<p>An equilateral triangle has perimeter 624 cm. Its height is k√3 cm, where k is a constant.</p><p><strong>What is the value of k?</strong></p>', '[]', '["104"]', '<p>The correct answer is 104. Each side of the triangle is 624/3 = 208 cm. The height of an equilateral triangle with side s is (s&radic;3)/2, which here is (208&radic;3)/2 = 104&radic;3. So k = 104.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_math_m2_q21', NULL, 'Math', 'Problem-Solving and Data Analysis', 'Hard', 'One-variable data: Distributions and measures of center and spread', '<p>Two histograms, same shape/frequencies (23 integers each), but Data Set A''s bins run 20-60 and Data Set B''s identical-shaped bins run 10-50 (each bin shifted down by exactly 10 from A).</p><p><strong>What is the smallest possible difference between the mean of Data Set A and the mean of Data Set B?</strong></p>', '[{"content":"0","letter":"A"},{"content":"1","letter":"B"},{"content":"10","letter":"C"},{"content":"23","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. Each bin of data set B sits exactly 10 below the matching bin of data set A, and the two sets have the same frequencies. The difference of the means is smallest when every value in A sits at the bottom of its bin and every value in B sits at the top of its. A value at the top of a B bin is 9 above that bin''s lowest value, which is itself 10 below the matching A bin''s lowest value, so it is 1 below the A value. Averaging, the means differ by 1.</p><p>Choice A is incorrect. Every value of A exceeds its matching value of B, so the means cannot be equal. Choice C is incorrect. 10 is the gap between the bin boundaries, which is the largest difference, not the smallest. Choice D is incorrect. 23 is the number of values, not a difference of means.</p>', 'Bluebook', 0, 0, NULL);
INSERT OR REPLACE INTO questions (id, external_id, section, domain, difficulty, skill, stem_html, choices_json, correct_answer, explanation_html, source, source_page, has_figure, stem_text) VALUES ('pt8_rw_m2_q13', NULL, 'Reading & Writing', 'Information and Ideas', 'Hard', 'Inferences', '<p>Some economists say firms adopt automation for productivity gains. Researchers found (1) those productivity gains are often unremarkable, and (2) the US tax code treats automation spending more favorably than equivalent labor spending.</p><p><strong>Together, these findings suggest that:</strong></p>', '[{"content":"The productivity/tax-benefit explanation may be based on overestimating both tax benefits and productivity gains.","letter":"A"},{"content":"Adoption may be driven more by the tax incentive than by genuine output benefits.","letter":"B"},{"content":"Equalizing the tax code would have little effect on productivity but might increase adoption.","letter":"C"},{"content":"Firms actually see decreased productivity from automation, masked by tax advantages.","letter":"D"}]', '["B"]', '<p>Choice B is the best answer. One finding weakens the productivity motive, since the gains are often unremarkable, and the other supplies an alternative, since the tax code favors automation spending over equivalent labor spending. Together they point to the tax incentive as the stronger driver.</p><p>Choice A is incorrect. Nothing suggests the tax benefits are overestimated. Choice C is incorrect. Equalizing the code would be expected to reduce adoption, not increase it. Choice D is incorrect. Unremarkable gains are not decreased ones.</p>', 'Bluebook', 0, 0, NULL);
